const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(options={}){
 const data={...options.data},raw={getItem:k=>data[k]??null,setItem(k,v){if(options.failMigration&&k==='forme-workspaces-v1')throw Error('quota');data[k]=String(v);},removeItem:k=>delete data[k]},node={textContent:'',attrs:{},setAttribute(k,v){this.attrs[k]=v;},removeAttribute:k=>delete node.attrs[k]},subscriptions=[];let user=options.user||null,startCalls=0,reloads=0;
 const account={get:()=>({configured:options.configured!==false,user}),async start(){startCalls++;if(options.wait)await options.wait;if(options.restored)user=options.restored;return {ok:options.success!==false};},subscribe(fn){subscriptions.push(fn);}};
 const window={localStorage:raw,document:{getElementById:()=>node},location:{hash:'#account',reload(){reloads++;}},FORME_AUTH:{create:()=>account},FORME_INTERFACE_TRANSLATIONS:{get:key=>key}};const context={window};for(const file of ['backup.js','workspaces.js','bootstrap.js'])vm.runInNewContext(fs.readFileSync(file,'utf8'),context);
 return {window,data,raw,node,account,get starts(){return startCalls;},get reloads(){return reloads;},switchUser(next,busy=false){user=next;for(const fn of subscriptions)fn({user,busy});}};
}
test('bootstrap waits for Auth restoration before selecting an account workspace',async()=>{let release;const a=setup({wait:new Promise(resolve=>{release=resolve;}),restored:{uid:'user-a',emailVerified:true}}),pending=a.window.FORME_BOOTSTRAP.start();assert.equal(a.window.FORME_BOOTSTRAP.workspace,null);assert.equal(a.node.attrs['aria-busy'],'true');release();await pending;assert.equal(a.window.FORME_BOOTSTRAP.workspace.uid,'user-a');assert.equal(a.node.attrs['aria-busy'],undefined);});
test('repeated bootstrap calls reuse one account initialization',async()=>{const a=setup();await Promise.all([a.window.FORME_BOOTSTRAP.start(),a.window.FORME_BOOTSTRAP.start()]);assert.equal(a.starts,1);});
test('unconfigured authentication keeps guest data available without an Auth request',async()=>{const a=setup({configured:false,data:{'forme-plan':'{"mon":"cal-start"}'}});await a.window.FORME_BOOTSTRAP.start();assert.equal(a.starts,0);assert.equal(a.window.FORME_BOOTSTRAP.workspace.uid,null);assert.equal(a.window.FORME_BOOTSTRAP.workspace.storage.getItem('forme-plan'),'{"mon":"cal-start"}');});
test('sign-out revokes old facade writes while keeping saved account progress',async()=>{const a=setup({user:{uid:'user-a',emailVerified:true},data:{'forme-plan':'{"mon":"cal-start"}'}});await a.window.FORME_BOOTSTRAP.start();const workspace=a.window.FORME_BOOTSTRAP.workspace;a.switchUser(null);assert.equal(a.reloads,1);assert.equal(a.window.location.hash,'#account');assert.throws(()=>workspace.storage.setItem('forme-plan','{}'),/workspace-changed/);assert.equal(a.data[workspace.physical('forme-plan')],'{"mon":"cal-start"}');});
test('new sign-in selects home and reloads instead of reusing guest model instances',async()=>{const a=setup();await a.window.FORME_BOOTSTRAP.start();a.switchUser({uid:'user-a',emailVerified:true});assert.equal(a.reloads,1);assert.equal(a.window.location.hash,'#home');assert.equal(a.window.FORME_BOOTSTRAP.workspace.active(),false);});
test('verification updates for the same UID do not cause a reload or lose local data',async()=>{const a=setup({user:{uid:'user-a',emailVerified:false}});await a.window.FORME_BOOTSTRAP.start();a.switchUser({uid:'user-a',emailVerified:true});assert.equal(a.reloads,0);assert.equal(a.window.FORME_BOOTSTRAP.workspace.active(),true);});
test('failed workspace migration retains guest originals and reports storage failure',async()=>{const a=setup({user:{uid:'user-a',emailVerified:true},failMigration:true,data:{'forme-plan':'{"mon":"cal-start"}'}});await a.window.FORME_BOOTSTRAP.start();assert.equal(a.window.FORME_BOOTSTRAP.workspaceProblem,true);assert.equal(a.window.FORME_BOOTSTRAP.workspace.uid,null);assert.equal(a.data['forme-plan'],'{"mon":"cal-start"}');assert.equal(a.raw.getItem('forme-workspaces-v1'),null);});
test('temporary startup failure never clears an already restored account or its local data',async()=>{const a=setup({user:{uid:'user-a',emailVerified:true},success:false,data:{'forme-plan':'{"mon":"cal-start"}'}});await a.window.FORME_BOOTSTRAP.start();assert.equal(a.window.FORME_BOOTSTRAP.workspace.uid,'user-a');assert.equal(a.window.FORME_BOOTSTRAP.workspace.storage.getItem('forme-plan'),'{"mon":"cal-start"}');});

test('navigation waits for Auth operation completion so verification mail is not interrupted',async()=>{const a=setup();await a.window.FORME_BOOTSTRAP.start();a.switchUser({uid:'user-a',emailVerified:false},true);assert.equal(a.reloads,0);assert.equal(a.window.FORME_BOOTSTRAP.workspace.active(),false);a.switchUser({uid:'user-a',emailVerified:false},false);assert.equal(a.reloads,1);});
test('registration can keep the profile route while login still opens home',async()=>{const a=setup();await a.window.FORME_BOOTSTRAP.start();a.window.FORME_BOOTSTRAP.setSwitchTarget('#account');a.switchUser({uid:'user-a',emailVerified:false});assert.equal(a.window.location.hash,'#account');});
